create table public.uf_platform(id integer primary key check(id=1),data jsonb not null,revision integer not null default 1,updated_at timestamptz not null default now());
create table public.uf_signal(id integer primary key check(id=1),revision integer not null default 1,updated_at timestamptz not null default now());
create table public.uf_accounts(id uuid primary key default gen_random_uuid(),username text not null unique,name text not null,role text not null check(role in('student','teacher','admin')),group_id text not null default '',subgroup text not null default '',teacher_id text not null default '',active boolean not null default true,salt text not null,password_hash text not null,created_at timestamptz not null default now());
create table public.uf_sessions(token_hash text primary key,user_id text not null,expires_at timestamptz not null);
create index uf_sessions_expires on public.uf_sessions(expires_at);
create table public.uf_versions(revision integer primary key,data jsonb not null,actor text not null,reason text not null,created_at timestamptz not null default now());
alter table public.uf_platform enable row level security;alter table public.uf_signal enable row level security;alter table public.uf_accounts enable row level security;alter table public.uf_sessions enable row level security;alter table public.uf_versions enable row level security;
revoke all on public.uf_platform,public.uf_signal,public.uf_accounts,public.uf_sessions,public.uf_versions from public,anon,authenticated;
grant all on public.uf_platform,public.uf_signal,public.uf_accounts,public.uf_sessions,public.uf_versions to service_role;
grant select on public.uf_signal to anon,authenticated;
create policy uf_signal_read on public.uf_signal for select to anon,authenticated using(true);
